		/* updateMasterMpSoIssueManageRemarkProcessType */
			UPDATE KEP_PO_MNG 
			SET STATUS = #{st_status},
				NOTICE_DATE = '',
				KEP_REMARK = #{st_remark},
				CONFIRM_USER_ID = #{st_user_id},
				CONFIRM_DATE = SYSDATE
			WHERE BUYER = #{st_buyer}
			AND PO_NO = #{st_po_no}
			AND TYPE = #{st_type}			
			AND STATUS = 'S'


            AND PO_SEQ = #{st_po_seq}
