            AND SEQ = #{st_seq}


/* updateMasterMpSoIssueProcessTypePrdt */
	UPDATE	ICOMPRDT
	SET		PROCESS_TYPE = #{st_process_type}
	WHERE	1=1
	AND		(BUYER, PR_NO, PR_SEQ) IN (SELECT BUYER, PR_NO, PR_SEQ FROM ICOMPODT WHERE BUYER = #{st_buyer} AND PO_NO = #{st_po_no} AND STATUS <> 'D')
	AND		STATUS <> 'D'


/* updateMasterMpSoIssueProcessTypePodt */
	UPDATE	ICOMPODT
	SET		STATUS = 'R',
			CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
			CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'),
			PROCESS_TYPE = #{st_process_type},
			WAREHOUSE_CODE = ''
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PO_NO = #{st_po_no}


/* updateMasterMpSoIssueProcessTypePohd */
	UPDATE	ICOMPOHD
	SET		STATUS = 'R',
			CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
			CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'),
			PROCESS_TYPE = #{st_process_type},
			PARCEL_YN = #{st_parcel}
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PO_NO = #{st_po_no}
	AND		STATUS <> 'D'


/* updateMasterMpSoIssueDsDatePors */
	UPDATE	ICOMPORS A
	SET		A.CD_DATE = (SELECT CH_DS_DATE FROM KEP_PO_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND DS_SEQ = A.DS_SEQ AND SEQ = #{st_seq} AND STATUS <> 'D'),
			A.DS_DATE = (SELECT CH_DS_DATE FROM KEP_PO_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND DS_SEQ = A.DS_SEQ AND SEQ = #{st_seq} AND STATUS <> 'D'),
			A.BUYER_DS_DATE = DECODE(#{st_process_type_code},'0',(SELECT CH_DS_DATE FROM KEP_PO_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND DS_SEQ = A.DS_SEQ AND SEQ = #{st_seq} AND STATUS <> 'D'),
			                                                 '2',KEP.F_GET_WMS_DS(#{st_buyer},#{st_warehouse_code},(SELECT CH_DS_DATE FROM KEP_PO_MNG WHERE BUYER = A.BUYER AND PO_NO = A.PO_NO AND PO_SEQ = A.PO_SEQ AND DS_SEQ = A.DS_SEQ AND SEQ = #{st_seq} AND STATUS <> 'D'))),
			A.CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
			A.CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'),
			A.CHANGE_USER_ID = #{st_user_id}
	WHERE	1=1
	AND		A.BUYER = #{st_buyer}
	AND		A.PO_NO = #{st_po_no}
	AND		A.PO_SEQ = #{st_po_seq}
	AND		A.DS_SEQ  = #{st_ds_seq}
	AND		A.STATUS <> 'D'

