/* updateMasterMpSoIssueClearPors */
	UPDATE	ICOMPORS
	SET		STATUS = 'D',
			CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
			CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
	WHERE	1=1
	AND		BUYER = #{st_buyer}
	AND		PO_NO = #{st_po_no}
	AND		STATUS <> 'D'


/* updateMasterMpSoIssueManageRemarkAfterVoc */
	UPDATE	KEP_PO_MNG 
	SET		ATOA_REMARK = ATOA_REMARK || ', VOC : ' || #{st_vc_no}
	WHERE	1=1
	AND		BUYER = #{st_buyer_code}
	AND		PO_NO = #{st_po_no}
	AND		PO_SEQ = #{st_po_seq}
	AND		SEQ = #{st_seq}
	AND		TYPE = 'E'			
	AND		STATUS = 'S'

/* insertMasterMpSoIssueManageMemo */ INSERT INTO KEP_PO_MNG ( BUYER, PO_NO, PO_SEQ, DS_SEQ, SEQ, PR_NO, PR_SEQ, AGENT, STATUS, TYPE, AGENT_REMARK, ADD_USER_ID, ADD_DATE, CHANGE_USER_ID, CHANGE_DATE, NOTICE_DATE, CONFIRM_USER_ID, CONFIRM_DATE ) ( SELECT BUYER, PO_NO, PO_SEQ, DS_SEQ, NEW_SEQ, PR_NO, PR_SEQ, AGENT, STATUS, TYPE, AGENT_REMARK, ADD_USER_ID, ADD_DATE, CHANGE_USER_ID, CHANGE_DATE, NOTICE_DATE, CONFIRM_USER_ID, CONFIRM_DATE FROM ( SELECT PO.BUYER, PO.PO_NO, PO.PO_SEQ, '000000' AS DS_SEQ, ( SELECT NVL(MAX(SEQ),0)+1 FROM KEP_PO_MNG MN WHERE MN.BUYER = PO.BUYER AND MN.PO_NO = PO.PO_NO AND MN.PO_SEQ = PO.PO_SEQ AND MN.DS_SEQ = '000000' ) AS NEW_SEQ, PO.PR_NO, PO.PR_SEQ, PH.AGENT, #{st_status} AS STATUS, 'C' AS TYPE, #{st_remark} AS AGENT_REMARK, #{st_user_id} AS ADD_USER_ID, SYSDATE AS ADD_DATE, #{st_user_id} AS CHANGE_USER_ID, SYSDATE AS CHANGE_DATE,
'' AS NOTICE_DATE, #{st_user_id} AS CONFIRM_USER_ID, SYSDATE AS CONFIRM_DATE
#{st_notice_date} AS NOTICE_DATE, '' AS CONFIRM_USER_ID, '' AS CONFIRM_DATE
FROM ICOMPODT PO, ICOMPOHD PH WHERE PO.BUYER = #{st_buyer} AND PO.STATUS <> 'D' AND PO.PO_NO = #{st_po_no}
AND PO.PO_SEQ = #{st_po_seq}
AND PH.BUYER = PO.BUYER AND PH.PO_NO = PO.PO_NO ) )


/* insertMasterMpSoIssueManageMemo2 */
UPDATE	ICOMPODT PO
SET		SCM_REMARK = SCM_REMARK||'^^'||TO_CHAR(SYSDATE,'YYYYMMDD')||'@@'||(SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = #{st_user_id})||'@@'||#{st_memo_remark}
WHERE	PO.BUYER = #{st_buyer}
AND		PO.PO_NO = #{st_po_no}



AND		PO.PO_SEQ = #{st_po_seq}
